(async () => {
  const p = new PrismaClient();
  const slugs = Object.keys(translations);
  let updated = 0;
  for (const slug of slugs) {
    const tr = translations[slug];
    const data: Record<string, unknown> = {};
    for (const lang of ["fr", "es", "de"] as const) {
      const t = tr[lang];
      if (!t) continue;
      const clean: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(t)) {
        if (typeof v === "string" && v.trim()) clean[k] = v;
      }
      data[lang] = clean;
    }
    if (Object.keys(data).length === 0) continue;
    const res = await p.product.updateMany({
      where: { slug },
      data: { translations: data as never },
    });
    updated += res.count;
    console.log(`Updated ${slug}: ${res.count} row(s)`);
  }
  console.log(`\nTotal updated: ${updated}`);
  await p.$disconnect();
})();
